// build-mr-bundle.js —— 把 renderer/mr/ 下的 MR 模块拼成单个 bundle（机制等同 MR index-loader.js
// 的"合并为单 script 执行"：跨文件 function 声明提升，00-core-stores 顶层 read* 调用才能命中）。
// 用法：node scripts/build-mr-bundle.js（renderer/mr/ 下模块有变动后重新生成）
'use strict';
const fs = require('fs'), path = require('path');
const ROOT = path.join(__dirname, '..', 'renderer', 'mr');
const FILES = [
  'vendor/three.r128.min.js',
  '00-state/00-core-stores.js', '00-state/01-perf-render-state.js', '00-state/02-preferences-ui-modes.js',
  '00-state/03-beat-dj-state.js', '00-state/04-fx-defaults.js', '00-state/05-packaged-fx-archive.js',
  '00-state/06-fx-runtime-layout.js', '00-state/07-ui-playback-runtime.js', '00-state/08-desktop-render-power.js',
  '00-state/09-performance-probe.js', '00-state/10-frame-scheduler.js', '00-state/11-system-memory-controls.js',
  'vendor/gsap.min.js',
  '01-scene/00-renderer-quality.js', '01-scene/01-orbit-free-camera.js', '01-scene/02-beat-camera-runtime.js',
  '01-scene/03-focus-cinema-camera.js',
  '01-scene/04-bottom-controls-cursor.js',
  '02-visual/00-pointer-cover-particles.js', '02-visual/01-float-skull-backcover.js',
  '02-visual/02-lyrics-state-layout.js', '02-visual/03-lyrics-star-river.js', '02-visual/04-visual-settings-persistence.js',
  '02-visual/05-lyrics-fonts-texture.js',
  '02-visual/07-lyrics-palette-text-utils.js', '02-visual/08-lyrics-display-modes.js', '02-visual/09-lyrics-payloads.js',
  '02-visual/10-lyrics-mask-textures.js', '02-visual/11-lyrics-shaders.js', '02-visual/12-lyrics-row-layers.js',
  '02-visual/06-custom-background-colorlab.js', '02-visual/15-ripples-cover-depth.js',
  '02-visual/13-lyrics-mesh-build.js', '02-visual/14-stage-lyrics-rendering.js',
  // B-1 离线节拍链（2026-09-20）：MR index-loader 顺序 03-beat/00 在 01 之前；
  // 配套 vendor/music-tempo.min.js（UMD 挂 window.MusicTempo）+ music-tempo-worker.js（真实文件 worker，
  // CSP 拦 blob worker 的替代——见 00 头部适配说明）。worker 文件不进 bundle（运行时 new Worker 单独加载）。
  '03-beat/00-tempo-worker-cache-prefetch.js',
  '03-beat/01-audio-beat-analysis.js', '03-beat/04-beat-map-runtime.js', '03-beat/05-cover-loading-crop.js',
  '07-fx/00-preset-archive-data.js', '07-fx/01-lyric-color-controls.js', '07-fx/02-accent-background-controls.js',
  '07-fx/03-cover-picker-fonts.js', '07-fx/04-preset-grid-uniforms.js', '07-fx/05-fx-panel-performance.js',
  '07-fx/08-cache-storage-settings.js',
  '07-fx/03-wallpaper-engine-library.js',
  '07-fx/09-console-workspace.js',
  '09-idle-toast-libraries.js',
  'sonic-topography-preset.js',
  'sonic-workshop-preset.js', // B-a 音域回响·WE 预设 8（2026-09-20；bridge/assets 在 vendor/sonic-workshop/，运行时 iframe 加载，不进 bundle）
  '03-beat/06-sonic-audio-monitor.js',
  '04-shelf/00-layout-hover.js', '04-shelf/01-manager-core.js', '04-shelf/02-rebuild-panel-sync.js',
  '04-shelf/03-content-list-manager.js', '04-shelf/04-cover-api-helpers.js', '04-shelf/05-card-interactions.js', '04-shelf/06-keyboard-camera-events.js',
  '07-fx/07-bindings-shelf-immersive.js', '05-playback/06-track-detail-lyrics-actions.js', '05-playback/07-audio-output-ui.js',
  '05-playback/15-control-glass-animations.js', // B-b 控制玻璃子系统（色差滑条真身；MR index-loader 顺序在本段）
  '06-lyrics/06-lyric-timing-offset.js', '06-lyrics/07-lyric-render-helpers.js',
  // 10-shell 段（MR index-loader.js 顺序：10-shell 在 09-idle-toast 之后；05-startup-bindings 等未 vendor）
  '10-shell/00-gesture-control.js',
  // D-1 修复：07-fx/00:18896 applyFxArchiveSnapshot 无条件调用本文件的 applyWallpaperModeState
  // （07-fx 多处调用 pushWallpaperState/desktopWallpaperErrorLabel），此前已 vendor 未入清单
  // → fx 预设存档应用半程 ReferenceError、fx 控制台历史回退恒失败。顶层仅一条 320ms 健康巡检
  // interval，守卫分支 desktopLyrics/wallpaperMode 在 DSH 均为安全桩（适配层 pushDesktopLyricsState no-op、
  // fx.wallpaperMode 默认 false 且唯一入口 toggle 在 bundle 后段仍可调、与 MR 行为一致）。
  '10-shell/04-desktop-overlay-fullscreen.js',
];
let out = '// MR-BUNDLE v1 (auto-generated by scripts/build-mr-bundle.js — do not edit)\n'
  + '// Source: Mineradio 2.2.0 public/js/modules (GPL-3.0) + three.js r128 (MIT)。原文拼合，未改动逻辑。\n';
for (const f of FILES) {
  out += '\n// ==================== ' + f + ' ====================\n';
  out += fs.readFileSync(path.join(ROOT, f), 'utf8').replace(/\r\n/g, '\n').trimEnd();
  out += '\n;\n';
}
fs.writeFileSync(path.join(ROOT, 'mr-bundle.js'), out, 'utf8');
console.log('mr-bundle.js written:', out.length, 'bytes');
